#include <bits/stdc++.h>
using namespace std;
class Solution {public:vector<int> arrayChange(vector<int>& nums,vector<vector<int>>& operations){unordered_map<int,int> pos;for(int i=0;i<(int)nums.size();++i)pos[nums[i]]=i;for(auto& op:operations){int i=pos[op[0]];pos.erase(op[0]);nums[i]=op[1];pos[op[1]]=i;}return nums;}};
